export const CHART_DEFAULTS=Object.freeze({upColor:'#00ff6a',downColor:'#ff2d2d',chartBackground:'#112018',gridColor:'#40533b',axisColor:'#ffffff',candleBodies:true,candleBorders:true,candleWicks:true,hollowCandles:true,colorPrevious:false,horizontalGrid:true,verticalGrid:false,lastPrice:true});
const KEY='rillvane.chart-appearance.v3',colors=['upColor','downColor','chartBackground','gridColor','axisColor'];
export function sanitizeChartPreferences(value={}){
 const result={...CHART_DEFAULTS};
 for(const key of Object.keys(result))if(colors.includes(key)){if(typeof value[key]==='string'&&/^#[0-9a-f]{6}$/i.test(value[key]))result[key]=value[key].toLowerCase();}else if(typeof value[key]==='boolean')result[key]=value[key];
 // Keep candles visible when a corrupted preference disables every part.
 if(!result.candleBodies&&!result.candleBorders&&!result.candleWicks)result.candleBorders=true;
 return result;
}
export function loadChartPreferences(){try{return sanitizeChartPreferences(JSON.parse(localStorage.getItem(KEY))||{});}catch{return {...CHART_DEFAULTS};}}
export function saveChartPreferences(value){const clean=sanitizeChartPreferences(value);try{localStorage.setItem(KEY,JSON.stringify(clean));}catch{}return clean;}
export function chartSettingsContent(prefs,tab='symbol'){
 const p=sanitizeChartPreferences(prefs),toggle=(key,label,note='')=>`<label class="chart-pref-toggle"><span><strong>${label}</strong>${note?`<small>${note}</small>`:''}</span><input type="checkbox" data-chart-pref="${key}" ${p[key]?'checked':''}></label>`;
 const color=(key,label)=>`<label class="chart-pref-color"><span>${label}</span><span><code>${p[key].toUpperCase()}</code><input type="color" data-chart-pref="${key}" value="${p[key]}" aria-label="${label}"></span></label>`;
 const sections={symbol:`<p class="chart-pref-eyebrow">CANDLE APPEARANCE</p><div class="chart-pref-color-pair">${color('upColor','Up candle color')}${color('downColor','Down candle color')}</div>${toggle('hollowCandles','Transparent bodies','Outlined candles with a lighter body fill.')}${toggle('candleBodies','Body fill')}${toggle('candleBorders','Borders')}${toggle('candleWicks','Wicks')}${toggle('colorPrevious','Color by previous close','Use the previous close instead of the candle open.')}`,scales:`<p class="chart-pref-eyebrow">SCALES & LINES</p>${toggle('lastPrice','Last price line')}${toggle('horizontalGrid','Horizontal grid')}${toggle('verticalGrid','Vertical grid')}${color('gridColor','Grid color')}${color('axisColor','Scale text color')}`,canvas:`<p class="chart-pref-eyebrow">CANVAS</p>${color('chartBackground','Chart background')}<p class="chart-pref-note">Choose a quiet chart surface. Your colors are saved in this browser and apply to the RLVN/USDC chart.</p><div class="reference-swatches"><i style="background:${p.chartBackground}"></i><i style="background:${p.upColor}"></i><i style="background:${p.downColor}"></i><i></i></div>`};
 return `<p class="modal-intro">Set the chart up for the way you read the market.</p><div class="chart-pref-layout"><nav aria-label="Chart settings sections">${[['symbol','Candles'],['scales','Scales & lines'],['canvas','Canvas']].map(([key,label])=>`<button data-action="chart-settings-tab" data-value="${key}" aria-pressed="${key===tab}" class="${key===tab?'active':''}">${label}</button>`).join('')}</nav><div class="chart-pref-section">${sections[tab]||sections.symbol}</div></div><div class="modal-actions"><button class="secondary-button" data-action="chart-reset">Reset chart colors</button><button class="primary-button" data-action="close-modal">Done</button></div>`;
}
